#!/usr/bin/env node
'use strict';

const USAGE = 'Usage: node slug.js "<title>"';
const MAX_ERROR = 'Error: --max needs a whole number greater than 0';

// Letters that Unicode decomposition does not split into a plain letter and an accent.
const SPECIAL_LETTERS = {
  ß: 'ss', æ: 'ae', œ: 'oe',
  ø: 'o', ł: 'l', đ: 'd', ħ: 'h', ŧ: 't', ƀ: 'b', ƶ: 'z', ǥ: 'g', ɨ: 'i', ƚ: 'l',
};
const SPECIAL_LETTER_PATTERN = new RegExp(`[${Object.keys(SPECIAL_LETTERS).join('')}]`, 'g');

function slugify(title) {
  return title
    .toLowerCase()
    .replace(SPECIAL_LETTER_PATTERN, (letter) => SPECIAL_LETTERS[letter])
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Cuts a slug to the most whole words that fit in max characters; a first word
// longer than max is cut at exactly max.
function truncate(slug, max) {
  if (slug.length <= max) return slug;
  let kept = '';
  for (const word of slug.split('-')) {
    const next = kept ? `${kept}-${word}` : word;
    if (next.length > max) break;
    kept = next;
  }
  return kept || slug.slice(0, max);
}

// Splits arguments into title words and the last --max value given.
// maxValue is undefined when --max is absent and null when it has no value.
function parseArgs(args) {
  const words = [];
  let maxValue;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--max') {
      maxValue = i + 1 < args.length ? args[++i] : null;
    } else if (args[i].startsWith('--max=')) {
      maxValue = args[i].slice('--max='.length);
    } else {
      words.push(args[i]);
    }
  }
  return { words, maxValue };
}

function main(args) {
  if (args.length === 1 && (args[0] === '--help' || args[0] === '-h')) {
    console.log(USAGE);
    return 0;
  }
  const { words, maxValue } = parseArgs(args);
  let max = Infinity;
  if (maxValue !== undefined) {
    if (maxValue === null || !/^[0-9]+$/.test(maxValue) || Number(maxValue) === 0) {
      console.error(MAX_ERROR);
      return 1;
    }
    max = Number(maxValue);
  }
  const slug = slugify(words.join(' '));
  if (!slug) {
    console.error(USAGE);
    return 1;
  }
  console.log(truncate(slug, max));
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = { slugify, truncate };
{
  "name": "slug",
  "version": "1.0.0",
  "private": true,
  "description": "Turn a title into a URL slug from the command line.",
  "scripts": {
    "test": "node --test"
  }
}
